"""Write the numbers of docs/15-prototype.md from the archives made by tools/prototype_archive.py, so they cannot drift.

    uv run python tools/prototype_numbers.py            # print every generated block
    uv run python tools/prototype_numbers.py --write    # rewrite the blocks inside docs/15
    uv run python tools/prototype_numbers.py --check    # exit 1, naming the block, if docs/15 differs

In docs/15 each table of numbers sits between a pair of marker comments

    <!-- BEGIN generated by tools/prototype_numbers.py: NAME -->
    ...
    <!-- END generated: NAME -->

and text outside the markers is never touched. Every number, every verdict (passed, failed, not run), every frame
number and every count inside a block comes from the JSON files in data/preview/ that the product wrote on this machine
(`asrp compare`, `asrp run`, tools/ziva_comparison.py): prototype_compare_<mesh>_<full_face|lips_only>.json,
prototype_ziva_comparison_<mesh>.json, prototype_run_<mesh>_<aa|jaw>.json, prototype_archive_manifest.json and
landmark_layer_check.json. The explanatory Chinese words in a row are fixed text in this file. A claim the files do not
hold is not written: a layer that is not identical to the other says so with its numbers instead of the sentence
"identical".

A few numbers in the page's running text belong to other documents (ADR-44, the T-33 and T-34 cards, E-20); they are
quoted, not recomputed, and the page says so where it quotes them. QUOTES below lists each quoted string with the
document it comes from: --check fails when the string is not in that document or no longer in docs/15, so a quote
cannot outlive its source.

After a new archive (tools/prototype_archive.py) run this tool with --write. tests/test_prototype_page.py runs --check,
so tools/verify.py fails when the page and the archives disagree.
"""

import argparse
import json
import re
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]
DOC = REPO / "docs" / "15-prototype.md"
PREVIEW = REPO / "data" / "preview"

BEGIN = "<!-- BEGIN generated by tools/prototype_numbers.py: {name} -->"
END = "<!-- END generated: {name} -->"
MARKER = re.compile(r"<!-- (?:BEGIN generated by tools/prototype_numbers\.py|END generated): ([\w-]+) -->")

MESHES = ("coarse", "fine")
MESH_NAME = {"coarse": "粗格子（面板默认）", "fine": "细网格"}
REFERENCES = ("full_face", "lips_only")
REFERENCE_NAME = {"full_face": "Ziva 整张脸（参照）", "lips_only": "Ziva 只留嘴唇（我们做的对照）"}
FRAMES = (36, 46)  # the end of the AA motion, and the last frame of the hold
SAG_FRAME = 14
SAME_MM = 1e-4  # two layers closer than this are "the same": the reports hold float32 numbers rounded to 6 places
CHECKS = (("a", "Motion completed"), ("b", "Hard attachments"), ("b2", "Spring anchors"),
          ("c", "Gravity sag"), ("d", "Tet mesh valid"))

# Numbers of the page's running text that belong to other documents: (the document, the exact string, which must be in
# the document and in docs/15). Quoted, not recomputed; the page says where each one comes from.
QUOTES = [
    ("docs/10-decisions.md", "12.1 mm"), ("docs/10-decisions.md", "9.3 mm"), ("docs/10-decisions.md", "27.0 mm"),
    ("docs/10-decisions.md", "0.4 mm"), ("docs/10-decisions.md", "平均 1.88–2.19"),
    ("docs/10-decisions.md", "上唇都被带动了（4.8–5.6 mm）"),
    ("docs/13-explanations.md", "上唇中间"), ("docs/13-explanations.md", "0.15"), ("docs/13-explanations.md", "4.80"),
    ("docs/09-roadmap-and-tasks.md", "0.000016 mm"),
    ("docs/09-roadmap-and-tasks.md", "145 份"),
    ("docs/09-roadmap-and-tasks.md", "| A | smooth | 91 | 67 | 45 | 56 | 0.255 |"),
    ("docs/09-roadmap-and-tasks.md", "| B | smooth | 72 | 194 | 80 | 38 | 0.152 |"),
    ("docs/09-roadmap-and-tasks.md", "| A | 折线 | 192 | 72 | 42 | 81 | 0.567 |"),
    ("docs/09-roadmap-and-tasks.md", "| B | 折线 | 79 | 115 | 64 | 50 | 0.313 |"),
]


# ---------------------------------------------------------------- small helpers


def table(header: list[str], rows: list[list[str]]) -> str:
    lines = ["| " + " | ".join(header) + " |", "|" + "---|" * len(header)]
    lines += ["| " + " | ".join(r) + " |" for r in rows]
    return "\n".join(lines)


def num(x: float, digits: int = 2) -> str:
    return f"{x:.{digits}f}"


def read_json(path: Path) -> dict:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise SystemExit(f"cannot read the archive {path.name}: {e}. Run tools/prototype_archive.py") from None


def verdict(check: dict) -> str:
    """The check's verdict as the page words it: only the JSON decides."""
    return {True: "通过", False: "**不通过**", None: "没运行"}[check["passed"]]


def triple(layer: dict, frame: int) -> str:
    return " / ".join(num(layer[key][frame]) for key in ("mean_mm", "p95_mm", "max_mm"))


def after(frames) -> str:
    return "时窗内没有达到" if frames is None else f"第 {frames} 帧"


class Archive:
    """Everything the blocks need, read once."""

    def __init__(self, preview: Path = PREVIEW):
        self.compare = {(m, r): read_json(preview / f"prototype_compare_{m}_{r}.json") for m in MESHES for r in REFERENCES}
        self.zc = {m: read_json(preview / f"prototype_ziva_comparison_{m}.json") for m in MESHES}
        self.run = {(m, k): read_json(preview / f"prototype_run_{m}_{k}.json") for m in MESHES for k in ("aa", "jaw")}
        self.manifest = read_json(preview / "prototype_archive_manifest.json")
        self.landmark = read_json(preview / "landmark_layer_check.json")
        self.old_run = read_json(preview / "prototype_run_report.json")  # the earlier run the README's picture came from


# ---------------------------------------------------------------- the blocks


def block_aa_distance(a: Archive) -> str:
    rows = []
    for mesh in MESHES:
        for ref in REFERENCES:
            physics = a.compare[(mesh, ref)]["layers"]["physics"]
            rows.append([MESH_NAME[mesh], REFERENCE_NAME[ref]] + [triple(physics, f) for f in FRAMES])
    return table(["我们的网格", "比的是谁", f"第 {FRAMES[0]} 帧：平均 / P95 / 最大（mm）",
                  f"第 {FRAMES[1]} 帧：平均 / P95 / 最大（mm）"], rows)


def block_aa_final(a: Archive) -> str:
    """The sentence about the final shape: 'the same numbers' only when the archive says they are the same."""
    worst = (0.0, None)
    for (mesh, ref), report in a.compare.items():
        for f in FRAMES:
            for key in ("mean_mm", "p95_mm", "max_mm"):
                d = abs(report["layers"]["final"][key][f] - report["layers"]["physics"][key][f])
                if d > worst[0]:
                    worst = (d, (mesh, ref, f))
    if worst[0] <= SAME_MM:
        return (f"最终形状（物理层叠上 landmark 层）在第 {FRAMES[0]}、{FRAMES[1]} 帧的平均、P95、最大和上表相同"
                f"（四份报告里最大相差 {worst[0]:.1g} mm，是浮点取整）：两边叠的是同一个 landmark 层，差别全部来自物理层。")
    mesh, ref, f = worst[1]
    return (f"最终形状和物理层的差在第 {FRAMES[0]}、{FRAMES[1]} 帧不相同，最大相差 {worst[0]:.3g} mm"
            f"（{MESH_NAME[mesh]}，{REFERENCE_NAME[ref]}，第 {f} 帧）；上表只是物理层。")


def block_gravity(a: Archive) -> str:
    rows = []
    for mesh in MESHES:
        sag = a.zc[mesh]["gravity_sag"]["ours"]
        rows.append([f"我们：{MESH_NAME[mesh]}", num(sag["mean_mm"][SAG_FRAME], 3), num(sag["max_mm"][SAG_FRAME], 3),
                     f"{sag['step_frame_13_to_14_max_mm']:.2g}"])
    sag = a.zc["coarse"]["gravity_sag"]
    for key, name in (("ziva_full_face", "Ziva 整张脸（参照）"), ("ziva_lips_only", "Ziva 只留嘴唇（还在下落，不是停稳的数）")):
        rows.append([name, num(sag[key]["mean_mm"][SAG_FRAME], 3), num(sag[key]["max_mm"][SAG_FRAME], 3),
                     f"{sag[key]['step_frame_13_to_14_max_mm']:.2g}"])
    return table([f"谁（第 {SAG_FRAME} 帧对第 0 帧）", "平均下垂（mm）", "最大（mm）", "第 13 到 14 帧最大还在动（mm）"], rows)


def block_surface(a: Archive) -> str:
    rows = []

    def row(name: str, entry: dict) -> list[str]:
        w, last = entry["worst"], entry["last"]
        return [name, f"第 {w['frame']} 帧：{w['flipped']} 个 / {w['short_edges']} 条",
                f"第 {last['frame']} 帧：{last['flipped']} 个 / {last['short_edges']} 条"]

    for mesh in MESHES:
        surface = a.zc[mesh]["surface"]
        rows.append(row(f"我们：{MESH_NAME[mesh]}，物理层", surface["ours_physics"]))
        rows.append(row(f"我们：{MESH_NAME[mesh]}，最终形状", surface["ours_final"]))
    surface = a.zc["coarse"]["surface"]
    for key, name in (("ziva_full_face_physics", "Ziva 整张脸，物理层"), ("ziva_full_face_final", "Ziva 整张脸，最终形状"),
                      ("ziva_lips_only_final", "Ziva 只留嘴唇，最终形状")):
        rows.append(row(name, surface[key]))
    return table(["谁", "翻转面最多的一帧：翻转面 / 过短的边", "最后一帧：翻转面 / 过短的边"], rows)


def block_speed(a: Archive) -> str:
    rows = []
    for mesh in MESHES:
        s = a.zc[mesh]["speed"]["ours"]
        rows.append([MESH_NAME[mesh], f"{s['mesh']['tets']:,}", f"{s['mesh']['nodes']:,}", str(s["frames"]),
                     f"{s['febio_s']:.2f}", f"{s['febio_s_per_frame']:.3f}"])
    first = a.zc["coarse"]["speed"]["ours"]
    m = a.manifest
    log = a.zc["coarse"]["speed"]["ziva"]["solver_log"]
    lines = [table(["网格", "四面体", "计算点", "帧数", "FEBio 用时（秒）", "每帧（秒）"], rows), "",
             f"Ziva 整张脸（实验室的机器）每步：{log['full_face_s_per_step']}；只留嘴唇每步：{log['lips_only_s_per_step']}"
             "（引自 13 E-15 的 Maya 求解器日志，不是本机测的；报告原文是英文）。", "",
             f"机器：{m['machine']}，FEBio {first['febio_threads']} 线程；同时在跑的事：{m['what_else_ran']}。"
             f"存档日期 {m['date']}，提交 {m['git_commit']}。"]
    return "\n".join(lines)


def block_shake(a: Archive) -> str:
    rows = []
    for mesh in MESHES:
        ours = a.zc[mesh]["head_shake"]["ours"]
        rows.append([f"我们：{MESH_NAME[mesh]}（只有嘴唇，每帧 1 步）", num(ours["wobble"]["max_mm"], 3),
                     f"第 {ours['wobble']['frame']} 帧", after(ours["decay"]["first_below"]),
                     after(ours["decay"]["stays_below"])])
    z = a.zc["coarse"]["head_shake"]["ziva"]
    rows.append(["Ziva（整张脸，只移动了颅骨和下颌）", num(z["wobble"]["max_mm"], 3), f"第 {z['wobble']['frame']} 帧",
                 after(z["decay"]["first_below"]), after(z["decay"]["stays_below"])])
    stop, limit = z["decay"]["stop_frame"], z["decay"]["limit_mm"]
    return table(["谁", "嘴唇相对颅骨的最大晃动（mm）", "出现在", f"停下（第 {stop} 帧）后第一次低于 {limit} mm",
                  f"停下后一直低于 {limit} mm"], rows)


def block_checks(a: Archive) -> str:
    rows = []
    for key, name in CHECKS:
        cells = []
        for mesh in MESHES:
            check = a.run[(mesh, "aa")]["checks"][key]
            cells.append(verdict(check) if check["passed"] is True else f"{verdict(check)}：{check['message']}")
        rows.append([f"({key}) {name}"] + cells)
    rows.append(["FEBio 缩小步长重算的次数"] + [str(a.run[(m, "aa")]["checks"]["a"]["numbers"]["retries"]) for m in MESHES])
    return table(["检查（面板 Checks 小节的名字）"] + [f"{MESH_NAME[m]}：中性到 AA" for m in MESHES], rows)


def block_jaw(a: Archive) -> str:
    rows = []
    for mesh in MESHES:
        report = a.run[(mesh, "jaw")]
        checks = report["checks"]
        passed = [k for k, c in checks.items() if c["passed"] is True]
        not_run = [k for k, c in checks.items() if c["passed"] is None]
        failed = [k for k, c in checks.items() if c["passed"] is False]
        rows.append([MESH_NAME[mesh], str(report["frames"]), str(checks["a"]["numbers"]["retries"]),
                     f"通过 {len(passed)} 项，没运行 {len(not_run)} 项" + (f"（{'、'.join(not_run)}）" if not_run else "")
                     + f"，不通过 {len(failed)} 项" + (f"（{'、'.join(failed)}）" if failed else "")])
    return table(["网格", "帧数", "FEBio 缩小步长重算的次数", "合理性检查"], rows)


def block_landmark(a: Archive) -> str:
    d = a.landmark
    return table(["核对", "结果"], [
        ["对象", f"{d['landmarks']} 个 landmark，{d['vertices']:,} 个显示顶点"],
        ["我们的蒙皮对实验室公式（实验室自己的绑定姿态和权重文件）最大差", f"{d['ours_vs_lab_formula_max_mm']:.2g} mm（平均 {d['ours_vs_lab_formula_mean_mm']:.2g} mm）"],
        ["门限", f"{d['limit_mm']:g} mm"],
        ["命令", f"`{d['command']}`"]])


def block_source(a: Archive) -> str:
    m = a.manifest
    z = m["ziva_runs"]
    return (f"存档日期 {m['date']}，提交 {m['git_commit']}；Ziva 的两次运行：整张脸 `{z['full_face']}`，"
            f"只留嘴唇 `{z['lips_only']}`；做法：`uv run python tools/prototype_archive.py`。")


BLOCKS = {
    "aa-distance": block_aa_distance, "aa-final": block_aa_final, "gravity": block_gravity, "surface": block_surface,
    "speed": block_speed, "shake": block_shake, "checks": block_checks, "jaw": block_jaw, "landmark": block_landmark,
    "source": block_source,
}


def load(preview: Path = PREVIEW) -> dict[str, str]:
    archive = Archive(preview)
    return {name: fn(archive) for name, fn in BLOCKS.items()}


def facts(a: Archive) -> list[tuple[str, bool, str]]:
    """Numbers and claims in the page's running text that the archives can settle: (the string docs/15 must hold,
    whether the archives say it, what it is). The page's words come from this list's strings; the digits come from
    the archives, so a new archive that moves one makes --check fail until the page is read again."""
    zc = a.zc["coarse"]
    aa = zc["neutral_to_AA"]
    everything = json.dumps([a.zc, list(a.compare.values())], ensure_ascii=False)
    out: list[tuple[str, bool, str]] = []
    for mesh in MESHES:
        out.append((f"{a.zc[mesh]['speed']['ours']['mesh']['tets']:,} 个四面体", True, f"tets of the {mesh} mesh"))
        material = a.zc[mesh]["settings"]["material"]
        out.append((f"杨氏模量 {material['E_mpa']['value'] * 1000:g} kPa、泊松比 {material['nu']['value']:g}",
                    material["E_mpa"]["source"] == "lab_setting", f"the {mesh} run's material"))
    out.append((f"格边 {zc['speed']['ziva']['mesh']['lips_tet_size_mm']:.2f} mm", True, "Ziva's tet size in mm"))
    out.append((f"下颌转 −{abs(zc['driver']['our_jaw_degrees'][FRAMES[0]]):.2f}°", True, "the jaw at the end of the motion"))
    first, last = aa["motion_frames"]
    hold_first, hold_last = aa["hold_frames"]
    out.append((f"第 {first} 到 {last} 帧是运动", last == FRAMES[0], "the motion frames"))
    out.append((f"第 {hold_first} 到 {hold_last} 帧停住不动", hold_last == FRAMES[1], "the hold frames"))
    out.append((f"第 {SAG_FRAME} 帧是只有重力的沉降的最后一帧", zc["gravity_sag"]["frames"][-1] == SAG_FRAME,
                "the last frame of the settle"))
    out.append((f"{aa['vertices']:,} 个顶点", True, "the lip vertices compared"))
    gap = max(zc["neutral_to_AA"]["ziva_full_face_against_ziva_lips_only_physics"]["max_mm"])
    out.append((f"整段里最多差 {gap:.1f} mm", True, "Ziva full face against Ziva lips only, largest of all frames"))
    out.append((f"{zc['head_shake']['ziva']['wobble']['max_mm']:.3f} mm", True, "Ziva's head shake, lips against the skull"))
    out.append(("41 块软组织", "41 tissues" in everything, "Ziva full face has 41 tissues"))
    out.append(("另外 42 个物体", "42 objects" in everything, "42 objects switched off in the lips-only run"))
    out.append(("另外 8 块骨头", "8 other bones" in json.dumps(zc["head_shake"], ensure_ascii=False),
                "8 bones did not move in Ziva's head shake"))
    closer = all(a.compare[("coarse", r)]["layers"]["physics"][k][f] < a.compare[("fine", r)]["layers"]["physics"][k][f]
                 for r in REFERENCES for f in FRAMES for k in ("mean_mm", "p95_mm", "max_mm"))
    out.append(("粗格子在上表的每一个数上都比细网格小", closer, "coarse is below fine in all 12 numbers of the table"))
    sag = zc["gravity_sag"]
    smaller = all(a.zc[m]["gravity_sag"]["ours"]["mean_mm"][SAG_FRAME] < sag["ziva_full_face"]["mean_mm"][SAG_FRAME]
                  for m in MESHES)
    out.append(("我们的下垂比 Ziva 小", smaller, "our mean sag is below Ziva's full face in both meshes"))
    out.append(("Ziva 自己的最终形状也有翻转面", zc["surface"]["ziva_full_face_final"]["worst"]["flipped"] > 0,
                "Ziva's own final shape has flipped faces"))
    out.append((f"{a.landmark['landmarks']} 个 landmark", True, "landmarks in the landmark-layer check"))
    old = next(p for p in a.old_run["parameters"] if p["where"].endswith("material.E_mpa"))
    out.append((f"材料还是我们定的 {old['value'] * 1000:g} kPa", old["source"] == "ours", "the earlier run's material"))
    return out


# ---------------------------------------------------------------- the markers in docs/15


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def find_blocks(text: str) -> tuple[dict[str, tuple[int, int]], list[str]]:
    """The span (start, end) of the text between each BEGIN/END pair, and the problems with the markers."""
    spans, problems, seen = {}, [], {}
    for m in MARKER.finditer(text):
        name = m.group(1)
        if m.group(0).startswith("<!-- BEGIN"):
            if name in seen:
                problems.append(f"block {name} begins twice")
            seen[name] = m.end()
        elif name not in seen:
            problems.append(f"block {name} ends before it begins")
        elif name in spans:
            problems.append(f"block {name} ends twice")
        else:
            spans[name] = (seen[name], m.start())
    problems += [f"block {name} has no end marker" for name in seen if name not in spans]
    return spans, problems


def rewrite(text: str, blocks: dict[str, str]) -> str:
    spans, problems = find_blocks(text)
    if problems:
        raise SystemExit("; ".join(problems))
    out, at = [], 0
    for name, (start, end) in sorted(spans.items(), key=lambda kv: kv[1][0]):
        if name not in blocks:
            raise SystemExit(f"docs/15 has a block {name!r} that this tool does not know")
        out.append(text[at:start])
        out.append("\n" + blocks[name] + "\n")
        at = end
    out.append(text[at:])
    return "".join(out)


def quote_problems(text: str, preview: Path = PREVIEW) -> list[str]:
    problems = []
    for string, said, what in facts(Archive(preview)):
        if not said:
            problems.append(f"the archives no longer say this: {what}")
        if string not in text:
            problems.append(f"docs/15 does not hold {string!r} ({what})")
    for doc, string in QUOTES:
        if string not in text:
            problems.append(f"docs/15 no longer holds the quoted {string!r}")
        source = REPO / doc
        if not source.is_file() or string not in read_text(source):
            problems.append(f"{doc} does not hold {string!r}, which docs/15 quotes from it")
    return problems


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--write", action="store_true")
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--doc", default=str(DOC))
    parser.add_argument("--preview", default=str(PREVIEW), help="the folder of the archives (default data/preview)")
    args = parser.parse_args()
    doc = Path(args.doc)
    preview = Path(args.preview)
    blocks = load(preview)
    if not (args.write or args.check):
        for name, text in blocks.items():
            print(f"--- {name}\n{text}\n")
        return
    text = read_text(doc)
    new = rewrite(text, blocks)
    if args.write:
        doc.write_text(new, encoding="utf-8", newline="\n")
        print(f"wrote {len(find_blocks(new)[0])} blocks into {doc.name}")
        return
    spans, problems = find_blocks(text)
    new_spans, _ = find_blocks(new)
    differs = [n for n in spans if text[spans[n][0]:spans[n][1]] != new[new_spans[n][0]:new_spans[n][1]]]
    problems += quote_problems(text, preview)
    if differs:
        print("docs/15 is out of date with the archives; run tools/prototype_numbers.py --write. "
              f"Differs in block(s): {', '.join(differs)}", file=sys.stderr)
    for p in problems:
        print(p, file=sys.stderr)
    sys.exit(1 if differs or problems else 0)


if __name__ == "__main__":
    main()
